  "settings.communityShareHint": "Separato da «I miei ascolti» e disattivato per impostazione predefinita. I tuoi voti agli album (senza commento) e gli ascolti ricevuti dal tuo account DOPO l'attivazione entrano in totali pubblici e anonimi, mostrati nella scheda dell'album a partire da tre persone distinte. Nessun dato individuale viene mai mostrato. Disattivarlo ritira subito il tuo contributo.",
  "settings.communityMeasuresReceive": "Ricevere i risultati di analisi della comunità",
  "settings.communityMeasuresReceiveHint": "Disattivato per impostazione predefinita. Per i tuoi FLAC, il server chiede a mozaiklabs.fr ReplayGain, gamme dinamiche e impronte acustiche già misurati esattamente sullo stesso segnale da almeno altre due installazioni. Colmano solo ciò che manca: i tuoi tag e le tue misure non vengono mai sostituiti. Il sito riceve solo un breve prefisso, mai l'elenco dei tuoi file.",
  "settings.communityMeasuresContribute": "Condividere i miei risultati di analisi con la comunità",
  "settings.communityMeasuresContributeHint": "Disattivato per impostazione predefinita. Il server invia al sito solo le misure che ha fatto da sé sui tuoi FLAC (ReplayGain, gamma dinamica, impronta acustica), identificate dalla firma del loro segnale. Non viene inviato alcun percorso, titolo, nome di file o account: il server si identifica con il suo numero di installazione. Disattivarlo cancella ciò che è stato inviato.",
